const lecturaMarcela = (r, z, u) => (r && z) || u;
const lecturaHugo = (r, z, u) => r && (z || u);

console.log('R Z U -> Marcela Hugo');
for (const r of [false, true])
  for (const z of [false, true])
    for (const u of [false, true]) {
      const m = lecturaMarcela(r, z, u);
      const h = lecturaHugo(r, z, u);
      console.log(+r, +z, +u, '->', +m, +h, m === h ? '' : '<- difieren');
    }

let todoOk = true;
for (const a of [false, true])
  for (const b of [false, true]) {
    if (!(a && b) !== (!a || !b)) todoOk = false;
    if (!(a || b) !== (!a && !b)) todoOk = false;
  }
console.log('De Morgan se cumple en las 4 combinaciones:', todoOk);

